(function(){
  if (window.SignaturePad) return;
  class SignaturePad {
    constructor(canvas, options) {
      this.canvas = canvas;
      this.ctx = canvas.getContext("2d");
      this.penColor = (options && options.penColor) || "#111";
      this.minWidth = (options && options.minWidth) || 1;
      this.maxWidth = (options && options.maxWidth) || 2;
      this.empty = true;
      this.drawing = false;
      this.listeners = {};
      this.ctx.lineCap = "round";
      this.ctx.lineJoin = "round";
      this.ctx.strokeStyle = this.penColor;
      this.ctx.lineWidth = this.maxWidth;
      this._bind();
    }
    addEventListener(name, callback) {
      this.listeners[name] = callback;
    }
    _emit(name) {
      if (typeof this.listeners[name] === "function") this.listeners[name]();
    }
    _point(event) {
      const rect = this.canvas.getBoundingClientRect();
      const src = event.touches && event.touches.length ? event.touches[0] : event;
      return {
        x: (src.clientX - rect.left) * (this.canvas.width / rect.width),
        y: (src.clientY - rect.top) * (this.canvas.height / rect.height)
      };
    }
    _bind() {
      const start = (event) => {
        event.preventDefault();
        const p = this._point(event);
        this.drawing = true;
        this.empty = false;
        this.ctx.beginPath();
        this.ctx.moveTo(p.x, p.y);
        this._emit("beginStroke");
      };
      const move = (event) => {
        if (!this.drawing) return;
        event.preventDefault();
        const p = this._point(event);
        this.ctx.lineTo(p.x, p.y);
        this.ctx.stroke();
      };
      const end = (event) => {
        if (!this.drawing) return;
        event.preventDefault();
        this.drawing = false;
      };
      this.canvas.addEventListener("mousedown", start);
      this.canvas.addEventListener("mousemove", move);
      document.addEventListener("mouseup", end);
      this.canvas.addEventListener("touchstart", start, { passive: false });
      this.canvas.addEventListener("touchmove", move, { passive: false });
      document.addEventListener("touchend", end, { passive: false });
    }
    clear() {
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
      this.empty = true;
    }
    isEmpty() {
      return this.empty;
    }
    toDataURL(type) {
      return this.canvas.toDataURL(type || "image/png");
    }
  }
  window.SignaturePad = SignaturePad;
})();
